import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/moran_local_2022_ghg.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute neighborhood means
neighborhood_means = {}
for index, row in adjacency.iterrows():
    borough = row['borough']
    neighbors = adjacency.loc[adjacency['neighbor'] == borough, 'borough'].values
    if len(neighbors) > 0:
        neighborhood_means[borough] = np.mean(df.loc[df['borough'].isin(neighbors), 'GHG_value'].values)

# Compute local Moran's I
local_morans_i = {}
for index, row in df.iterrows():
    borough = row['borough']
    mean_neighbors = neighborhood_means[borough]
    local_morans_i[borough] = (df.loc[df['borough'] == borough, 'GHG_value'].values[0] - mean_neighbors) / (df['GHG_value'].std() * np.sqrt(1 + (1 / len(df))))

# Determine hot and cold spots
hot_spots = []
cold_spots = []
for borough, value in local_morans_i.items():
    if df.loc[df['borough'] == borough, 'GHG_value'].values[0] > 2.5 and value > 0.1:
        hot_spots.append(borough)
    elif df.loc[df['borough'] == borough, 'GHG_value'].values[0] < 1.5 and value < -0.1:
        cold_spots.append(borough)

# Perform permutation test
p_values = {}
for borough in hot_spots + cold_spots:
    values = df['GHG_value'].values
    values[values == df.loc[df['borough'] == borough, 'GHG_value'].values[0]] = np.random.permutation(values[values == df.loc[df['borough'] == borough, 'GHG_value'].values[0]])
    p_values[borough] = np.mean([local_morans_i[borough] > (df.loc[df['borough'] == borough, 'GHG_value'].values[0] - neighborhood_means[borough]) / (df['GHG_value'].std() * np.sqrt(1 + (1 / len(df)))) for _ in range(500)])

# Report results
data_points_used = len(df)
final_answer = []
for borough in hot_spots:
    if p_values[borough] < 0.05:
        final_answer.append(f'{borough} (HH, Moran\'s I = {local_morans_i[borough]}, p-value = {p_values[borough]})')
for borough in cold_spots:
    if p_values[borough] < 0.05:
        final_answer.append(f'{borough} (LL, Moran\'s I = {local_morans_i[borough]}, p-value = {p_values[borough]})')

print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {", ".join(final_answer)}')
